  from jsonb_to_recordset($j$[{"topic":"history","band":"c6-8","difficulty":2,"q":"মহেঞ্জোদারো ও হরপ্পা কোন সভ্যতার নিদর্শন?","options":["মেসোপটেমীয় সভ্যতা","সিন্ধু সভ্যতা","চীনা সভ্যতা","মিসরীয় সভ্যতা"],"answer_idx":1,"explanation":"সিন্ধু সভ্যতা।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":2,"q":"মৌর্য সম্রাট অশোক কোন যুদ্ধের পর বৌদ্ধধর্ম গ্রহণ করেন?","options":["পানিপথের যুদ্ধ","কলিঙ্গ যুদ্ধ","বক্সারের যুদ্ধ","পলাশীর যুদ্ধ"],"answer_idx":1,"explanation":"কলিঙ্গ যুদ্ধ।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"মোগল সম্রাট আকবর যে নতুন ধর্মমত প্রবর্তনের চেষ্টা করেন তার নাম কী?","options":["ব্রাহ্ম ধর্ম","দীন-ই-ইলাহী","শিখ ধর্ম","জৈন ধর্ম"],"answer_idx":1,"explanation":"দীন-ই-ইলাহী।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":1,"q":"\"ঢাকাই মসলিন\" কীসের জন্য বিখ্যাত ছিল?","options":["কাঠের আসবাব","চামড়ার জুতা","অত্যন্ত মিহি সুতি কাপড়","মোটা পশমি কাপড়"],"answer_idx":2,"explanation":"অত্যন্ত মিহি সুতি কাপড়।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"ইংরেজ ইস্ট ইন্ডিয়া কোম্পানি কত সালে প্রতিষ্ঠিত হয়?","options":["১৬০০","১৮৫৭","১৫২৬","১৭০০"],"answer_idx":0,"explanation":"১৬০০।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"পলাশীর যুদ্ধের সময় বাংলার রাজধানী কোথায় ছিল?","options":["কলকাতা","মুর্শিদাবাদ","ঢাকা","চট্টগ্রাম"],"answer_idx":1,"explanation":"মুর্শিদাবাদ।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"ইউনেস্কো \"জামদানি বুননশিল্প\"-কে মানবতার অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় কত সালে অন্তর্ভুক্ত করে?","options":["২০২০","২০১৩","২০১৬","২০১৭"],"answer_idx":1,"explanation":"জামদানি বুননশিল্প: ২০১৩ সালে ইউনেস্কোর তালিকায়।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"ইউনেস্কো \"বাউল গান\"-কে মানবতার অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় কত সালে অন্তর্ভুক্ত করে?","options":["২০০৫","২০০৮","২০১৭","২০২০"],"answer_idx":1,"explanation":"বাউল গান: ২০০৮ সালে ইউনেস্কোর তালিকায়।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"ইউনেস্কো \"মঙ্গল শোভাযাত্রা (পহেলা বৈশাখ)\"-কে মানবতার অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় কত সালে অন্তর্ভুক্ত করে?","options":["২০০৫","২০১৬","২০১৩","২০২০"],"answer_idx":1,"explanation":"মঙ্গল শোভাযাত্রা (পহেলা বৈশাখ): ২০১৬ সালে ইউনেস্কোর তালিকায়।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":3,"q":"ইউনেস্কো \"শীতলপাটি বুননশিল্প\"-কে মানবতার অধরা সাংস্কৃতিক ঐতিহ্যের তালিকায় কত সালে অন্তর্ভুক্ত করে?","options":["২০১৩","২০০৮","২০১৭","২০১৬"],"answer_idx":2,"explanation":"শীতলপাটি বুননশিল্প: ২০১৭ সালে ইউনেস্কোর তালিকায়।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":1,"q":"\"জামদানি\" কী?","options":["একটি নদী","একটি খেলা","বাংলাদেশের ঐতিহ্যবাহী বুননের শাড়ি","এক ধরনের মাছ"],"answer_idx":2,"explanation":"বাংলাদেশের ঐতিহ্যবাহী বুননের শাড়ি।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":1,"q":"পহেলা বৈশাখে ঢাকায় বের হওয়া ঐতিহ্যবাহী শোভাযাত্রার নাম কী?","options":["জয়বাংলা মিছিল","মঙ্গল শোভাযাত্রা","বিজয় র‍্যালি","প্রভাতফেরি"],"answer_idx":1,"explanation":"মঙ্গল শোভাযাত্রা।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"},{"topic":"history","band":"c6-8","difficulty":1,"q":"২১ ফেব্রুয়ারির ভোরে শহীদ মিনারে যে অনুষ্ঠান হয় তার নাম কী?","options":["প্রভাতফেরি","র‍্যালি","আনন্দমেলা","মঙ্গল শোভাযাত্রা"],"answer_idx":0,"explanation":"প্রভাতফেরি।","source":"ইতিহাস ও সংস্কৃতি (৬ষ্ঠ-৮ম শ্রেণির পাঠ্যবই ও ইউনেস্কোর তালিকা)"}]$j$::jsonb) as x(topic text, band text, difficulty smallint, q text, options jsonb, answer_idx smallint, explanation text, source text)
 where not exists (select 1 from public.quiz_questions e where e.question = x.q);
-- 220 verified questions (math, band c6-8). Needs 2027-01-10_quiz_bank.sql. Safe to run twice: a question already in the bank is skipped.
insert into public.quiz_questions (topic, band, difficulty, question, options, answer_idx, explanation, source, status)
select x.topic, x.band, x.difficulty, x.q, x.options, x.answer_idx, x.explanation, x.source, 'verified'
  from jsonb_to_recordset($j$[{"topic":"math","band":"c6-8","difficulty":1,"q":"১৫০-এর ১০% কত?","options":["১৫০","৩০","২৫","১৫"],"answer_idx":3,"explanation":"১৫০ × ১০ ÷ ১০০ = ১৫।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"১৫-এর বর্গ কত?","options":["৩০","২২৫","২১০","২৪০"],"answer_idx":1,"explanation":"১৫² = ১৫ × ১৫ = ২২৫।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"√২৫৬ = কত?","options":["১৫","১৭","১৬","৩২"],"answer_idx":2,"explanation":"১৬ × ১৬ = ২৫৬, তাই বর্গমূল ১৬।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"x + ২০ = ৪১ হলে x = কত?","options":["২১","২২","৬১","২০"],"answer_idx":0,"explanation":"x = ৪১ − ২০ = ২১।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"৪x + ৮ = ৬৮ হলে x = কত?","options":["৬০","১৬","১৫","১৯"],"answer_idx":2,"explanation":"৪x = ৬৮ − ৮ = ৬০, তাই x = ৬০ ÷ ৪ = ১৫।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"২৫, ২৪, ৪৫, ৩৩, ৭৮ — এই সংখ্যাগুলোর গড় কত?","options":["৩৯","৪৩","২০৫","৪১"],"answer_idx":3,"explanation":"যোগফল = ২০৫, সংখ্যা ৫টা, গড় = ২০৫ ÷ ৫ = ৪১।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"দুইজনের টাকার অনুপাত ৮ : ৬। মোট ৭০ টাকা হলে প্রথমজনের অংশ কত টাকা?","options":["৬২","৪০","৪৮","৩০"],"answer_idx":1,"explanation":"মোট ভাগ = ৮ + ৬ = ১৪। এক ভাগ = ৭০ ÷ ১৪ = ৫। প্রথমজন = ৫ × ৮ = ৪০ টাকা।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"৩০০০ টাকার ৪% সরল হারে ২ বছরের মুনাফা কত টাকা?","options":["২৭০","২৪০","২৪০০","১২০"],"answer_idx":1,"explanation":"মুনাফা = (৩০০০ × ৪ × ২) ÷ ১০০ = ২৪০ টাকা।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"একটা ত্রিভুজের দুইটা কোণ ৪৭° ও ৬১°। তৃতীয় কোণটি কত ডিগ্রি?","options":["৭২","২৫২","১০৮","৪৩"],"answer_idx":0,"explanation":"ত্রিভুজের তিন কোণের সমষ্টি ১৮০°। তৃতীয় কোণ = ১৮০ − (৪৭ + ৬১) = ৭২°।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"একটা বৃত্তের ব্যাসার্ধ ৭ সেমি। ক্ষেত্রফল কত বর্গসেমি? (π = ২২/৭)","options":["৪৪","১৫৪","৭৭","২২"],"answer_idx":1,"explanation":"ক্ষেত্রফল = π r² = (২২/৭) × ৭ × ৭ = ১৫৪ বর্গসেমি।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"৫০০ টাকায় কেনা জিনিস ১০% লাভে বিক্রি করলে বিক্রয়মূল্য কত টাকা?","options":["৫০","৪৫০","৫৫০","৫১০"],"answer_idx":2,"explanation":"লাভ = ৫০০ × ১০ ÷ ১০০ = ৫০ টাকা। বিক্রয়মূল্য = ৫০০ + ৫০ = ৫৫০ টাকা।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":2,"q":"৬০ ও ২৮-এর গ.সা.গু. কত?","options":["৩২","৮","৪২০","৪"],"answer_idx":3,"explanation":"দুটো সংখ্যাকেই নিঃশেষে ভাগ করে এমন বৃহত্তম সংখ্যা ৪।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"২³ = কত?","options":["৮","৬","৪","১৬"],"answer_idx":0,"explanation":"২ কে ৩ বার গুণ করলে ৮।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"একটা গাড়ি ঘণ্টায় ৮০ কিমি বেগে ২ ঘণ্টা চললে কত কিমি যায়?","options":["৩২০","১৬০","৮২","৪০"],"answer_idx":1,"explanation":"দূরত্ব = বেগ × সময় = ৮০ × ২ = ১৬০ কিমি।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6-8","difficulty":1,"q":"৪০-এর ৪০% কত?","options":["১৬","১৬০","২৬","১"],"answer_idx":0,"explanation":"৪০ × ৪০ ÷ ১০০ = ১৬।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c6